import { useEffect, useMemo, useState } from "react";
import { LineChart } from "./Chart";
import { book, equity, LIMITS, newAccount, series, submit, SYMBOLS, type Account, type Order, type Sym } from "./sim";

const WARM = 200; // ticks of history already "played" when the demo opens
// Scripted sample run: one limit buy per stock at the third ask level, generated by this site's own simulator.
const sample = (() => {
  const marks = Object.fromEntries(SYMBOLS.map((s) => [s, series(s)[WARM]])) as Record<Sym, number>;
  let acct = newAccount();
  const rows = SYMBOLS.map((s) => {
    const b = book(s, WARM);
    const o: Order = { side: "buy", type: "limit", sym: s, qty: 20, limit: b.asks[2].price };
    const r = submit(acct, o, b, WARM, marks);
    acct = r.acct;
    return { o, filled: r.filled, avg: r.filled ? acct.fills.filter((f) => f.sym === s).reduce((t, f) => t + f.qty * f.price, 0) / r.filled : 0 };
  });
  return rows;
})();
const money = (n: number) => n.toLocaleString("en-US", { style: "currency", currency: "USD" });

export function Demo() {
  const [sym, setSym] = useState<Sym>("AAPL");
  const [tick, setTick] = useState(WARM);
  const [playing, setPlaying] = useState(false);
  const [acct, setAcct] = useState<Account>(newAccount);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [form, setForm] = useState({ side: "buy" as Order["side"], type: "market" as Order["type"], qty: "5", limit: "" });

  const all = useMemo(() => Object.fromEntries(SYMBOLS.map((s) => [s, series(s)])) as Record<Sym, number[]>, []);
  const marks = useMemo(() => Object.fromEntries(SYMBOLS.map((s) => [s, all[s][tick]])) as Record<Sym, number>, [all, tick]);
  const closes = all[sym];
  const bk = useMemo(() => book(sym, tick, closes), [sym, tick, closes]);

  useEffect(() => {
    if (!playing) return;
    const id = setInterval(() => setTick((t) => (t >= closes.length - 1 ? (setPlaying(false), t) : t + 1)), 700);
    return () => clearInterval(id);
  }, [playing, closes.length]);

  const place = (e: React.FormEvent) => {
    e.preventDefault();
    const order: Order = { side: form.side, type: form.type, sym, qty: Number(form.qty), limit: form.type === "limit" ? Number(form.limit) : undefined };
    const r = submit(acct, order, bk, tick, marks);
    if (r.error) return setMsg({ ok: false, text: `Rejected: ${r.error}` });
    setAcct(r.acct);
    setMsg(r.filled ? { ok: true, text: `Filled ${r.filled} of ${order.qty} ${sym} (simulated).` } : { ok: false, text: "No fill: the limit price did not cross the book, so the order was cancelled (immediate-or-cancel)." });
  };

  const eq = equity(acct, marks);
  const maxQty = Math.max(...bk.bids.map((l) => l.qty), ...bk.asks.map((l) => l.qty));
  return (
    <div className="stack">
      <div className="banner" role="note"><strong>Browser simulation.</strong> Prices are seeded random numbers, the order book is generated, and orders match against it inside your browser. This is not the C++ exchange and not market data. Same inputs always give the same output.</div>

      <fieldset className="picker">
        <legend>Stock</legend>
        {SYMBOLS.map((s) => (
          <label key={s} className={s === sym ? "chip on" : "chip"}>
            <input type="radio" name="sym" value={s} checked={s === sym} onChange={() => setSym(s)} />{s}
          </label>
        ))}
      </fieldset>

      <div className="grid2">
        <section aria-labelledby="h-chart" className="card">
          <h2 id="h-chart">{sym} synthetic price, trading days 0 to {tick}</h2>
          <LineChart values={closes.slice(0, tick + 1)} label={`${sym} synthetic daily price`} />
          <div className="row">
            <button type="button" onClick={() => setTick((t) => Math.min(t + 1, closes.length - 1))}>Next tick</button>
            <button type="button" aria-pressed={playing} onClick={() => setPlaying((p) => !p)}>{playing ? "Pause" : "Auto-play"}</button>
            <button type="button" onClick={() => { setTick(WARM); setAcct(newAccount()); setMsg(null); setPlaying(false); }}>Reset demo</button>
          </div>
        </section>

        <section aria-labelledby="h-book" className="card">
          <h2 id="h-book">Simulated order book</h2>
          <table className="book">
            <caption className="sr">Eight price levels on each side. Quantities are shares.</caption>
            <thead><tr><th scope="col">Bid qty</th><th scope="col">Bid</th><th scope="col">Ask</th><th scope="col">Ask qty</th></tr></thead>
            <tbody>
              {bk.bids.map((b, i) => (
                <tr key={i}>
                  <td><span className="depth bidd" style={{ width: `${(b.qty / maxQty) * 100}%` }} />{b.qty}</td><td>{b.price.toFixed(2)}</td>
                  <td>{bk.asks[i].price.toFixed(2)}</td><td><span className="depth askd" style={{ width: `${(bk.asks[i].qty / maxQty) * 100}%` }} />{bk.asks[i].qty}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </div>

      <div className="grid2">
        <section aria-labelledby="h-order" className="card">
          <h2 id="h-order">Paper order entry</h2>
          <form onSubmit={place}>
            <div className="fields">
              <label>Side<select value={form.side} onChange={(e) => setForm({ ...form, side: e.target.value as Order["side"] })}><option value="buy">Buy</option><option value="sell">Sell</option></select></label>
              <label>Type<select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value as Order["type"] })}><option value="market">Market</option><option value="limit">Limit (IOC)</option></select></label>
              <label>Shares<input inputMode="numeric" value={form.qty} onChange={(e) => setForm({ ...form, qty: e.target.value })} /></label>
              <label>Limit price<input inputMode="decimal" disabled={form.type !== "limit"} value={form.limit} placeholder={bk.asks[0].price.toFixed(2)} onChange={(e) => setForm({ ...form, limit: e.target.value })} /></label>
            </div>
            <button type="submit" className="primary">Send simulated order</button>
          </form>
          <p className="msg" role="status" aria-live="polite" data-ok={msg?.ok}>{msg?.text ?? "No orders yet."}</p>
          <p className="small">Risk limits (same as the Python bridge): {LIMITS.maxQty} shares per order, {money(LIMITS.maxOrderNotional)} per order, {money(LIMITS.maxPosition)} per stock, {money(LIMITS.maxGross)} total exposure, long-only.</p>
        </section>

        <section aria-labelledby="h-port" className="card">
          <h2 id="h-port">Portfolio (simulated money)</h2>
          <dl className="kv"><div><dt>Cash</dt><dd>{money(acct.cash)}</dd></div><div><dt>Equity</dt><dd>{money(eq)}</dd></div><div><dt>P&amp;L</dt><dd>{money(eq - LIMITS.startCash)}</dd></div></dl>
          <table>
            <caption className="sr">Positions</caption>
            <thead><tr><th scope="col">Stock</th><th scope="col">Shares</th><th scope="col">Value</th></tr></thead>
            <tbody>{SYMBOLS.filter((s) => acct.pos[s]).map((s) => <tr key={s}><td>{s}</td><td>{acct.pos[s]}</td><td>{money((acct.pos[s] ?? 0) * marks[s])}</td></tr>)}
              {!SYMBOLS.some((s) => acct.pos[s]) && <tr><td colSpan={3}>No positions.</td></tr>}</tbody>
          </table>
          <h3>Trade history</h3>
          <table>
            <caption className="sr">Simulated fills, newest first</caption>
            <thead><tr><th scope="col">Tick</th><th scope="col">Side</th><th scope="col">Stock</th><th scope="col">Qty</th><th scope="col">Price</th></tr></thead>
            <tbody>{[...acct.fills].reverse().slice(0, 12).map((f, i) => <tr key={i}><td>{f.tick}</td><td>{f.side}</td><td>{f.sym}</td><td>{f.qty}</td><td>{f.price.toFixed(2)}</td></tr>)}
              {!acct.fills.length && <tr><td colSpan={5}>No trades yet.</td></tr>}</tbody>
          </table>
        </section>
      </div>

      <section aria-labelledby="h-rec" className="card">
        <h2 id="h-rec">Scripted sample run</h2>
        <div className="banner alt" role="note"><strong>Generated demonstration data, not live.</strong> Produced by this page's own browser simulator from seeded random numbers. It is not output from the C++ exchange and not market data.</div>
        <p className="small">One immediate-or-cancel limit buy per stock, priced at the third ask level, run at trading day {WARM}. Fills depend only on the generated book.</p>
        <table>
          <caption className="sr">Planned orders and resulting fills</caption>
          <thead><tr><th scope="col">Stock</th><th scope="col">Planned qty</th><th scope="col">Limit</th><th scope="col">Filled qty</th><th scope="col">Avg fill price</th></tr></thead>
          <tbody>{sample.map(({ o, filled, avg }) => <tr key={o.sym}><td>{o.sym}</td><td>{o.qty}</td><td>{o.limit!.toFixed(2)}</td><td>{filled}</td><td>{filled ? avg.toFixed(2) : "-"}</td></tr>)}</tbody>
        </table>
      </section>
    </div>
  );
}
